for name,value in [('description',desc),('og:title',title),('og:description',desc)]:
 attr='property' if name.startswith('og:') else 'name'
 s=re.sub(r'<meta '+attr+'="'+name+r'" content="[^"]*">',f'<meta {attr}="{name}" content="{html.escape(value,quote=True)}">',s)
if 'og:locale' not in s:s=s.replace('</head>','<meta property="og:locale" content="vi_VN"><meta property="og:site_name" content="Lạc Hồng Viên – Kênh thông tin dự án"><meta name="twitter:card" content="summary_large_image"></head>')
base='https://congviennghiatrang.com/'
schema={'@context':'https://schema.org','@graph':[{'@type':'WebSite','@id':base+'#website','url':base,'name':'Lạc Hồng Viên – Kênh thông tin dự án','inLanguage':'vi-VN'},{'@type':'WebPage','@id':base+'#webpage','url':base,'name':title,'description':desc,'inLanguage':'vi-VN','isPartOf':{'@id':base+'#website'},'primaryImageOfPage':{'@type':'ImageObject','url':base+'wp-content/uploads/2026/10/lac-hong-vien-hoa-binh-35.jpg'}},{'@type':'FAQPage','@id':base+'#faq','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faqs]}]}
s=re.sub(r'<script type="application/ld\+json">.*?</script>',lambda m:'<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script>',s,flags=re.S)
p.write_text(s)
